  // worker/geography.mjs
  var CITIES = Object.freeze(cities_default.map((city) => Object.freeze(city)));
  var byId = new Map(CITIES.map((city) => [city.id, city]));
  var normalize = (value) => value.trim().toLocaleLowerCase("ru-RU").replaceAll("\u0451", "\u0435").replace(/[,\s]+/g, " ");
  var collator = new Intl.Collator("ru-RU");
  var featured = new Map(["\u041C\u043E\u0441\u043A\u0432\u0430", "\u0421\u0430\u043D\u043A\u0442-\u041F\u0435\u0442\u0435\u0440\u0431\u0443\u0440\u0433", "\u041A\u0440\u0430\u0441\u043D\u043E\u0434\u0430\u0440", "\u041D\u043E\u0432\u043E\u0441\u0438\u0431\u0438\u0440\u0441\u043A", "\u0415\u043A\u0430\u0442\u0435\u0440\u0438\u043D\u0431\u0443\u0440\u0433", "\u041A\u0430\u0437\u0430\u043D\u044C", "\u041D\u0438\u0436\u043D\u0438\u0439 \u041D\u043E\u0432\u0433\u043E\u0440\u043E\u0434", "\u0421\u0430\u043C\u0430\u0440\u0430", "\u0420\u043E\u0441\u0442\u043E\u0432-\u043D\u0430-\u0414\u043E\u043D\u0443", "\u0423\u0444\u0430", "\u041C\u0443\u0440\u043C\u0430\u043D\u0441\u043A"].map((name, index) => [name, index]));
  var searchable = CITIES.map((city) => ({ city, name: normalize(city.name), region: normalize(city.region) }));
  function findCity(id) {
    return typeof id === "string" ? byId.get(id) || null : null;
  }
  function isLocalCity(city) {
    return city?.name === "\u041A\u0440\u0430\u0441\u043D\u043E\u0434\u0430\u0440" && /Краснодар/i.test(city.region);
  }
  function searchCities(query) {
    const value = normalize(query);
    const tokens = value.split(" ").filter(Boolean);
    const matches = searchable.filter((entry) => {
      if (!value) return true;
      if (entry.name.startsWith(value) || entry.region.startsWith(value)) return true;
      const words = `${entry.name} ${entry.region}`.split(/[\s\-]+/);
      return tokens.every((token) => words.some((word) => word.startsWith(token)));
    });
    const rank = (entry) => entry.name === value ? 0 : featured.has(entry.city.name) && (!value || entry.name.startsWith(value)) ? 1 : entry.name.startsWith(value) ? 2 : 3;
    matches.sort((a, b) => rank(a) - rank(b) || (rank(a) === 1 && rank(b) === 1 ? featured.get(a.city.name) - featured.get(b.city.name) : 0) || collator.compare(a.city.name, b.city.name) || collator.compare(a.city.region, b.city.region));
    return { cities: matches.slice(0, 20).map((entry) => entry.city), total: matches.length, hasMore: matches.length > 20, directoryCount: CITIES.length };
  }
  function getDeliveryOptions(city) {
    const options = isLocalCity(city) ? [
      { id: "courier", label: "\u041A\u0443\u0440\u044C\u0435\u0440 \u043F\u043E \u041A\u0440\u0430\u0441\u043D\u043E\u0434\u0430\u0440\u0443", description: "\u041F\u043E \u0443\u043A\u0430\u0437\u0430\u043D\u043D\u043E\u043C\u0443 \u0430\u0434\u0440\u0435\u0441\u0443. \u0421\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u044C, \u0441\u0440\u043E\u043A\u0438, \u0440\u0430\u0437\u0433\u0440\u0443\u0437\u043A\u0430 \u0438 \u043F\u043E\u0434\u044A\u0451\u043C \u0441\u043E\u0433\u043B\u0430\u0441\u0443\u044E\u0442\u0441\u044F \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E.", requiresAddress: true, requiresConfirmation: true },
      { id: "pickup", label: "\u0421\u0430\u043C\u043E\u0432\u044B\u0432\u043E\u0437 \u0432 \u041A\u0440\u0430\u0441\u043D\u043E\u0434\u0430\u0440\u0435", description: "\u0412\u043E\u0437\u043C\u043E\u0436\u043D\u043E\u0441\u0442\u044C \u0441\u0430\u043C\u043E\u0432\u044B\u0432\u043E\u0437\u0430, \u0430\u0434\u0440\u0435\u0441 \u0441\u043A\u043B\u0430\u0434\u0430 \u0438 \u0432\u0440\u0435\u043C\u044F \u0432\u044B\u0434\u0430\u0447\u0438 \u043D\u0443\u0436\u043D\u043E \u0441\u043E\u0433\u043B\u0430\u0441\u043E\u0432\u0430\u0442\u044C \u0434\u043E \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043D\u0438\u044F \u0437\u0430\u044F\u0432\u043A\u0438.", requiresAddress: false, requiresConfirmation: true }
    ] : [
      { id: "terminal", label: "\u0414\u043E \u0433\u0440\u0443\u0437\u043E\u0432\u043E\u0433\u043E \u0442\u0435\u0440\u043C\u0438\u043D\u0430\u043B\u0430 \u0422\u041A", description: "\u041F\u0435\u0440\u0435\u0432\u043E\u0437\u0447\u0438\u043A, \u043F\u043E\u0434\u0445\u043E\u0434\u044F\u0449\u0438\u0439 \u0442\u0435\u0440\u043C\u0438\u043D\u0430\u043B, \u0435\u0433\u043E \u0430\u0434\u0440\u0435\u0441, \u0442\u0430\u0440\u0438\u0444 \u0438 \u0441\u0440\u043E\u043A \u0431\u0443\u0434\u0443\u0442 \u0441\u043E\u0433\u043B\u0430\u0441\u043E\u0432\u0430\u043D\u044B \u0434\u043E \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043D\u0438\u044F. \u0414\u043E\u0441\u0442\u0430\u0432\u043A\u0430 \u0434\u043E \u0434\u0432\u0435\u0440\u0438 \u043D\u0435 \u0432\u043A\u043B\u044E\u0447\u0435\u043D\u0430.", requiresAddress: false, requiresConfirmation: true }
    ];
    return { city, options, notice: "\u0412\u044B\u0431\u043E\u0440 \u0433\u043E\u0440\u043E\u0434\u0430 \u0444\u0438\u043A\u0441\u0438\u0440\u0443\u0435\u0442 \u043F\u043E\u0436\u0435\u043B\u0430\u043D\u0438\u0435 \u043F\u043E \u0434\u043E\u0441\u0442\u0430\u0432\u043A\u0435. \u041D\u0430\u043B\u0438\u0447\u0438\u0435 \u043F\u043E\u0434\u0445\u043E\u0434\u044F\u0449\u0435\u0433\u043E \u0442\u0435\u0440\u043C\u0438\u043D\u0430\u043B\u0430 \u0438 \u0432\u043E\u0437\u043C\u043E\u0436\u043D\u043E\u0441\u0442\u044C \u043F\u0435\u0440\u0435\u0432\u043E\u0437\u043A\u0438 \u043C\u0435\u0431\u0435\u043B\u0438 \u043D\u0443\u0436\u043D\u043E \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u044C. \u0422\u0430\u0440\u0438\u0444 \u043D\u0435 \u0440\u0430\u0441\u0441\u0447\u0438\u0442\u0430\u043D \u0438 \u043D\u0435 \u0432\u0445\u043E\u0434\u0438\u0442 \u0432 \u0441\u0443\u043C\u043C\u0443 \u0442\u043E\u0432\u0430\u0440\u043E\u0432." };
  }

